INSERT INTO vehicles (id, title, price, year, km, engine, transmission, fuel, body_type, condition, availability, origin, badge, description, images, catalog, status, mastertech) VALUES (1, 'Honda HR-V Sport 2025 4x4 AWD', '$36,000', 2025, '15,000 KM', '2.0L', 'Automático', 'Gasolina', 'suv', 'seminuevo', 'entrega_inmediata', 'nacional', 'ENTREGA INMEDIATA', 'Honda HR-V Sport 2025 con tracción 4x4 AWD. Motor 2.0L, transmisión automática. Ubicación Porlamar. Nivel de daño leve: golpe en puerta trasera piloto. 15,000 km recorridos. Entrega inmediata.', ARRAY['images/gallery/honda-hrv-sport-2025-4x4-awd/1.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/2.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/3.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/4.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/5.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/6.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/7.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/8.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/9.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/10.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/11.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/12.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/13.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/14.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/15.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/16.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/17.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/18.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/19.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/20.jpg','images/gallery/honda-hrv-sport-2025-4x4-awd/21.jpg']::text[], 'seminuevos', 'active', false) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, price = EXCLUDED.price, description = EXCLUDED.description, images = EXCLUDED.images, status = EXCLUDED.status;
